EXECUTE IMMEDIATE $$
DECLARE total INT DEFAULT 0;
BEGIN
    BEGIN
        LET cur CURSOR FOR SELECT v FROM test_db.test_schema.nums;
        FOR rec IN cur DO
            total := :total + rec.V;
        END FOR;
        CLOSE cur;
    END;
    RETURN :total;
END
$$

