    LET cx CURSOR FOR SELECT label FROM test_db.test_schema.nfl_labels ORDER BY label;
    FOR rx IN cx DO
        BEGIN
            LET cy CURSOR FOR SELECT cnt FROM test_db.test_schema.nfl_single;
            FOR ry IN cy DO
                result := :result || ry.CNT || ',';
            END FOR;
            CLOSE cy;
        END;
    END FOR;
    CLOSE cx;
    RETURN :result;
END
$$

